INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1un4y1f7by', 'course-bili-bv1un4y1f7by', '100001', '0', 'BILI-GRW-006', 'course-category-growth', 'instructor-bili-1115852727', '有声书《11堂极简系统思维课》｜怎样成为解决问题的高手', '6 讲完整课程 · 1 小时 26 分钟', '万维钢《精英日课》解读，并倾情作序，罗辑思维推荐。提升你的逻辑能力，更批判性地思考，运用系统思维解决问题，一切从翻开这本书开始。系统思维在帮助我们解决各种不同的复杂问题时非常有效。95%的人无法做到系统思考。', '课程简介：万维钢《精英日课》解读，并倾情作序，罗辑思维推荐。提升你的逻辑能力，更批判性地思考，运用系统思维解决问题，一切从翻开这本书开始。系统思维在帮助我们解决各种不同的复杂问题时非常有效。95%的人无法做到系统思考。作者以简练的语言与真实的事例，介绍了什么是系统思维、系统思维的要素，系统是如何运行的，如何将系统思维运用到你的工作与生活中。在这11堂系统思维课里，谈到了绩效、商业竞争、政策制定、人际关系等。本书展示了一个观察和思考这个世界的不同方式，将帮助你超越简单的因果关系，考虑到影响问题的每个因素，找到战略性解决方案，提高你的批判性思维、分析能力、有效解决问题的能力。课程结构：共 1 章 6 讲，累计时长 1 小时 26 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立可落地的目标拆解与时间管理系统","掌握专注力、精力与情绪调节的实用工具","形成稳定的阅读、复盘与知识沉淀习惯","把学习成果转化为长期可复用的个人能力"]', '["希望摆脱拖延与低效忙碌的学习者","需要平衡工作与成长的职场人","在校学生与自我提升人群"]', '["愿意记录并复盘自己的真实时间开销","无需任何专业背景"]', 'intermediate', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/5c74bc0a12ce899e0732be9578a951944ffcc64e.jpg', '["个人成长","时间管理","学习方法","有声书","11堂极简系统思维课","怎样成为解决问题的高手"]', 5200, 6, 8825, '4.4', 3870, 'BV1UN4y1F7bY', NULL, NULL, NULL, 1, 0, 'standard', NULL, '霸天硬核读书', 0, 'tenant', 'published', '2022-08-24T14:24:09.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
