INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1v44y1r7cs', 'course-bili-bv1v44y1r7cs', '100001', '0', 'BILI-GRW-017', 'course-category-growth', 'instructor-bili-87062222', '《自控力》：斯坦福大学最受欢迎心理学课程】1', '5 讲完整课程 · 9 小时 43 分钟', 'youtube 作为一名健康心理学家，凯利•麦格尼格尔博士的工作就是帮助人们管理压力，并在生活中做出积极的改变。通过观察学生们是如何控制选择的，人们关于自控的很多看法实际上妨碍了我们取得成功。', '课程简介：youtube 作为一名健康心理学家，凯利•麦格尼格尔博士的工作就是帮助人们管理压力，并在生活中做出积极的改变。通过观察学生们是如何控制选择的，人们关于自控的很多看法实际上妨碍了我们取得成功。把自控力当作一种美德，可能会让初衷良好的目标脱离正轨。麦格尼格尔要求她的学生了解影响自控的生理学基础、心理陷阱和各种社会因素。麦格尼格尔吸收了心理学、神经学和经济学等学科的最新洞见，为斯坦福大学继续教育项目开设了一门叫做“意志力科学”的课程，参与过这门课程的人称其能够“改变一生”。课程结构：共 1 章 5 讲，累计时长 9 小时 43 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立可落地的目标拆解与时间管理系统","掌握专注力、精力与情绪调节的实用工具","形成稳定的阅读、复盘与知识沉淀习惯","把学习成果转化为长期可复用的个人能力"]', '["希望摆脱拖延与低效忙碌的学习者","需要平衡工作与成长的职场人","在校学生与自我提升人群"]', '["愿意记录并复盘自己的真实时间开销","无需任何专业背景"]', 'beginner', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/c71a83126647e6add232827b3ea0313fa895336d.jpg', '["个人成长","时间管理","学习方法","有声书","自控力"]', 34997, 5, 23769, '4.4', 5659, 'BV1v44y1r7cS', '79.00', '126.40', 'CNY', 0, 0, 'standard', NULL, '底层逻辑2022', 0, 'tenant', 'published', '2021-05-21T11:13:34.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
