INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-6145220', 'course-bili-season-6145220', '100001', '0', 'BILI-GRW-039', 'course-category-growth', 'instructor-bili-3546561841728131', '哲学/社会学/世界观/人生观/价值观/心理学/思维/方法论', '55 讲完整课程 · 605 小时 47 分钟', '我们的梦想意味着什么？我们是天生的种族主义者吗？是什么让我们快乐？精神疾病的原因和', '我们的梦想意味着什么？我们是天生的种族主义者吗？是什么让我们快乐？精神疾病的原因和治疗方法是什么？本课程试图回答这些问题和其他许多问题，全面概述对思想和行为的科学研究。它探讨的主题包括感知、交流、学习、记忆、决策、说服、情感和社会行为。我们将研究这些方面的思维在儿童时期是如何发展的，它们在不同的人身上有什么不同，它们在大脑中是如何被连接起来的，以及它们是如何因疾病和损伤而崩溃的。课程结构：共 1 章 55 讲，累计时长 605 小时 47 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立可落地的目标拆解与时间管理系统","掌握专注力、精力与情绪调节的实用工具","形成稳定的阅读、复盘与知识沉淀习惯","把学习成果转化为长期可复用的个人能力"]', '["希望摆脱拖延与低效忙碌的学习者","需要平衡工作与成长的职场人","在校学生与自我提升人群"]', '["愿意记录并复盘自己的真实时间开销","无需任何专业背景"]', 'beginner', 'zh-CN', 'https://s1.hdslb.com/bfs/templar/york-static/viedeo_material_default.png', '["个人成长","时间管理","学习方法","哲学","社会学","世界观"]', 2180870, 55, 30255, '4.6', 16783, 'BV1hEUZBKEjQ', '199.00', '318.40', 'CNY', 0, 0, 'standard', NULL, '常春藤中英字幕课', 0, 'tenant', 'published', '2025-11-29T07:56:41.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
