INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-3570965', 'course-bili-season-3570965', '100001', '0', 'BILI-GRW-079', 'course-category-growth', 'instructor-bili-25435445', '30位up主教你决策！', '18 讲完整课程 · 3 小时 21 分钟', '距离上次更新3个月，这个系列终于做到了第三期，本期意识教程希望给到新手甚至部分老玩家一个系统的APEX意识体系，一开始文案超过1万字，但是由于篇幅原因删减到8000字以内，尽管如此时长也超过了25分钟，所以没有办法涉及过', '课程简介：距离上次更新3个月，这个系列终于做到了第三期，本期意识教程希望给到新手甚至部分老玩家一个系统的APEX意识体系，一开始文案超过1万字，但是由于篇幅原因删减到8000字以内，尽管如此时长也超过了25分钟，所以没有办法涉及过于具体的内容。非常感谢30位up主对于本期视频的大力支持，由于简介有艾特人数限制，我就不一个一个艾特了。由于制作周期限制，部分up主的回答较晚，原谅我实在没有办法把你们的回答加进来，因为一改就是从头到尾改，涉及到巨大的工作量，在此也对这部分up主表示歉意。视频中有任何错误与问题，欢迎评论区留言。我还没有搞懂这个东西到底怎么看 课程结构：共 3 章 18 讲，累计时长 3 小时 21 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立可落地的目标拆解与时间管理系统","掌握专注力、精力与情绪调节的实用工具","形成稳定的阅读、复盘与知识沉淀习惯","把学习成果转化为长期可复用的个人能力"]', '["希望摆脱拖延与低效忙碌的学习者","需要平衡工作与成长的职场人","在校学生与自我提升人群"]', '["愿意记录并复盘自己的真实时间开销","无需任何专业背景"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/0fd9d02e34441040fda98f77d6e27eeeaac32f9b.jpg', '["个人成长","时间管理","学习方法","APEX最卷意识入门","30位up主教你决策！"]', 12114, 18, 108429, '4.8', 14090, 'BV1pV4y1X77C', '49.00', '78.40', 'CNY', 0, 0, 'standard', NULL, '老葛你又在打电动', 0, 'tenant', 'published', '2023-03-24T13:01:29.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
