INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1pl411g7cy', 'course-bili-bv1pl411g7cy', '100001', '0', 'BILI-GRW-085', 'course-category-growth', 'instructor-bili-477041559', '自动驾驶汽车预测-决策-规划-控制实战入门', '18 讲完整课程 · 7 小时 27 分钟', '本期课程以S型道路作为自动驾驶换道场景，深入讲解轨迹预测、换道决策、路径规划、速度规划、跟踪控制的相关核心算法和思想和Matlab仿真，最后利用Simulink实现动态仿真。', '课程简介：本期课程以S型道路作为自动驾驶换道场景，深入讲解轨迹预测、换道决策、路径规划、速度规划、跟踪控制的相关核心算法和思想和Matlab仿真，最后利用Simulink实现动态仿真。课程结构：共 3 章 18 讲，累计时长 7 小时 27 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立可落地的目标拆解与时间管理系统","掌握专注力、精力与情绪调节的实用工具","形成稳定的阅读、复盘与知识沉淀习惯","把学习成果转化为长期可复用的个人能力"]', '["希望摆脱拖延与低效忙碌的学习者","需要平衡工作与成长的职场人","在校学生与自我提升人群"]', '["愿意记录并复盘自己的真实时间开销","无需任何专业背景"]', 'beginner', 'zh-CN', 'https://i2.hdslb.com/bfs/archive/011fa2c9874fe69b51d09f500409d79ffed0ac6a.png', '["个人成长","时间管理","学习方法","自动驾驶汽车预测","决策","规划"]', 26843, 18, 39640, '4.3', 8493, 'BV1PL411g7cY', '49.00', '78.40', 'CNY', 0, 0, 'standard', NULL, '小黎的Ally', 0, 'tenant', 'published', '2021-11-14T05:09:47.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
