INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-4571471', 'course-bili-season-4571471', '100001', '0', 'BILI-GRW-097', 'course-category-growth', 'instructor-bili-301388587', '布局2025！这样拆解年度目标 不烂尾！Notion目标管理系统', '33 讲完整课程 · 3 小时 9 分钟', '年度目标总是立了又放弃？如何让年度目标不再烂尾？我一直都是在用Notion做自己的目标、项目管理🎯 将大目标拆解成小步骤，设定截止时间，让目标真的能落地✨ 📌 我的目标设置步骤大概分成三步： 1. 先写下年度大目标', '课程简介：年度目标总是立了又放弃？如何让年度目标不再烂尾？我一直都是在用Notion做自己的目标、项目管理🎯 将大目标拆解成小步骤，设定截止时间，让目标真的能落地✨ 📌 我的目标设置步骤大概分成三步： 1. 先写下年度大目标：比如更新课程、学习新技能、开始副业账号等。2. 把目标拆解成具体任务：像学笛子，可以分成每节课完成的计划。点击新建任务，设置好截止时间，直观又明确！3. 有一些目标是需要每天坚持的日常好习惯：读书、运动、不生气、学习、不吃垃圾食品，这些可以通过每天打卡实现 这个系统通过了2年的迭代，能够满足我的所有目标管理需求，还能实时追踪目标完成情况，清楚看到哪些任务已完成，哪些还需要努力，🌟 把复杂的大目标一步步拆解，完成后成就感直接拉满！🔥希望也能让你的2025年变得高效又充实！🎉 课程结构：共 1 章 33 讲，累计时长 3 小时 9 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立可落地的目标拆解与时间管理系统","掌握专注力、精力与情绪调节的实用工具","形成稳定的阅读、复盘与知识沉淀习惯","把学习成果转化为长期可复用的个人能力"]', '["希望摆脱拖延与低效忙碌的学习者","需要平衡工作与成长的职场人","在校学生与自我提升人群"]', '["愿意记录并复盘自己的真实时间开销","无需任何专业背景"]', 'intermediate', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/6f289b7e782a619702603fa04af41513a4ef61be.jpg', '["个人成长","时间管理","学习方法"]', 11345, 33, 381, '4.4', 29, 'BV1mowAeEEwC', NULL, NULL, NULL, 1, 0, 'standard', NULL, 'Shiki实验室', 0, 'tenant', 'published', '2025-01-18T12:00:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
